using System.Text;
using VisionFramework;
using VisionPluginContracts;
namespace VisionPlugins.BranchString;
internal sealed class BranchStringRuntime(Action<ModuleExecutionContext,ModuleResult>? completed=null):IModule {
 public static readonly ModuleDescriptor Description=new("vision.branch-string","1.0.0","分支字符串",[new PortDescriptor("StringA",DataKind.Text,false){SupportsDeferredTextRead=true}],[new PortDescriptor("ModuRunTime",DataKind.Number,false),new("BranchMatch",DataKind.Text,false){CanSubscribe=false},new("StringMatch",DataKind.Text,false){CanSubscribe=false},new("ModuStatus",DataKind.Integer,false){CanSubscribe=false}],[new("ModuleInfoList",ParameterKind.Text,true,System.Text.Json.JsonSerializer.SerializeToElement(""))]);
 public ModuleDescriptor Descriptor=>Description;
 static ToolTextInputReadResult Read(ModuleExecutionContext c){const int capacity=0x100;if(c.Scope?.Service<IToolTextInputReader>() is {} reader)return reader.Read(c,"StringA",0,capacity);if(c.ReadTextInput?.Invoke("StringA",0,capacity) is {} read)return new(read.ErrorCode,read.Count,read.Value,read.RequiredBytes);if(!c.Inputs.TryGetValue("StringA",out var value)||value.Kind!=DataKind.Text)return new(0xe0000314,0,"",0);var values=value.Elements().ToArray();if(values.Length==0)return new(0xe0000314,0,"",0);string text=values[0].As<string>().Split('\0')[0];int required=checked(Encoding.UTF8.GetByteCount(text)+1);return required>capacity?new(0xe0000012,0,"",required):new(0,values.Length,text,required);}
 public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken cancellationToken){cancellationToken.ThrowIfCancellationRequested();ValueTask<ModuleResult> Done(ModuleResult result){completed?.Invoke(c,result);return ValueTask.FromResult(result);}var read=Read(c);if(read.ErrorCode!=0||read.Count<1)return Done(new(read.ErrorCode==0?ModuleStatus.Success:ModuleStatus.Failed,new Dictionary<string,PortValue>(),read.ErrorCode==0?null:"BranchStringInputRead"){NativeErrorCode=read.ErrorCode,SelectedExecutionSuccessors=Array.Empty<string>()});var timer=System.Diagnostics.Stopwatch.StartNew();string input=read.Value.Split('\0')[0];var selected=BranchStringProcess.Select(input,BranchStringTable.ReadCanonical(c.Text("ModuleInfoList")),c.ExecutionSuccessors.Select(n=>new BranchStringSuccessor(n.NodeId,n.NumericId)).ToArray(),read.RequiredBytes);var outputs=new Dictionary<string,PortValue>{{"ModuRunTime",PortValue.Number((float)timer.Elapsed.TotalMilliseconds)},{"StringMatch",PortValue.Text(input)},{"BranchMatch",PortValue.Text(selected.BranchMatch)},{"ModuStatus",PortValue.Integer(selected.ModuleStatus)}};return Done(new(ModuleStatus.Success,outputs,Message:selected.UsesNodeIdAdapter?"Independent NodeId identity adapter; native numeric instance ID mapping is unavailable.":null){NativeErrorCode=0,SelectedExecutionSuccessors=selected.NodeIds});}
}

